mapper.select:
select
f.file_relation_id as fileRelationId,
mn.*
from  OA_Attendance_Supplement mn
left join  Sys_File f on f.FileID=mn.As_Id
where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.As_Abnormal_State = #{params.asAbnormalState}


    and mn.As_State = #{params.asState}


    and mn.As_Uname like concat('%',#{params.asUname},'%')


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.As_Create_Time desc
    

limit #{params.start},#{params.size}

select
count(1)
from  OA_Attendance_Supplement mn
left join  Sys_File f on f.FileID=mn.As_Id
where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.As_Abnormal_State = #{params.asAbnormalState}


    and mn.As_State = #{params.asState}


    and mn.As_Uname like concat('%',#{params.asUname},'%')
